using System.Runtime.CompilerServices;

namespace MyApp.BuildingBlocks.Domain;

/// <summary>
/// An object defined by its identity. Two entities are equal when they have the same type and the same id;
/// an entity whose id is still the default value is equal only to itself. Equality compares the runtime type,
/// so proxy types generated by an ORM are not supported.
/// </summary>
/// <typeparam name="TId">The type of the id.</typeparam>
public abstract class Entity<TId> : IEquatable<Entity<TId>>
    where TId : notnull
{
    /// <summary>Initializes a new instance of the <see cref="Entity{TId}"/> class.</summary>
    /// <param name="id">The id, or the default value when the store assigns it.</param>
    protected Entity(TId id) => Id = id;

    /// <summary>Gets the id of the entity.</summary>
    public TId Id { get; }

    private bool IsTransient => EqualityComparer<TId>.Default.Equals(Id, default!);

    /// <summary>Returns a value indicating whether two entities are equal.</summary>
    /// <param name="left">The first entity.</param>
    /// <param name="right">The second entity.</param>
    /// <returns><see langword="true"/> when both are <see langword="null"/> or equal; otherwise <see langword="false"/>.</returns>
    public static bool operator ==(Entity<TId>? left, Entity<TId>? right) =>
        left is null ? right is null : left.Equals(right);

    /// <summary>Returns a value indicating whether two entities are not equal.</summary>
    /// <param name="left">The first entity.</param>
    /// <param name="right">The second entity.</param>
    /// <returns><see langword="true"/> when the entities are not equal; otherwise <see langword="false"/>.</returns>
    public static bool operator !=(Entity<TId>? left, Entity<TId>? right) => !(left == right);

    /// <inheritdoc />
    public bool Equals(Entity<TId>? other)
    {
        if (other is null)
        {
            return false;
        }

        if (ReferenceEquals(this, other))
        {
            return true;
        }

        return other.GetType() == GetType()
            && !IsTransient
            && !other.IsTransient
            && EqualityComparer<TId>.Default.Equals(Id, other.Id);
    }

    /// <inheritdoc />
    public override bool Equals(object? obj) => obj is Entity<TId> other && Equals(other);

    /// <summary>
    /// Returns a hash code based on the type and the id. A transient entity uses its reference instead, so do not
    /// keep it in a hash-based collection across the moment its id is assigned.
    /// </summary>
    /// <returns>The hash code.</returns>
    public override int GetHashCode() =>
        IsTransient ? RuntimeHelpers.GetHashCode(this) : HashCode.Combine(GetType(), Id);
}
